// The program inside an executable of the original Blitz compilers (Blitz3D, BlitzPlus, Blitz Basic).
//
// The executable is the runtime of the original with the compiled program as one resource (RT_RCDATA 1111), a relocatable x86 module:
//
//   u32 code_size; u8 code[code_size]            code and data of the program, starting at offset 0
//   u32 n; { cstr name; u32 offset } * n          labels: where the names that the program defines are
//   u32 n; { cstr name; u32 offset } * n          relative references: the 4 bytes at offset are a distance to the name (calls, jumps)
//   u32 n; { cstr name; u32 offset } * n          absolute references: the 4 bytes at offset are an address of the name plus what is there
#pragma once
#include <cstdint>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

namespace blitz::recompiler {
	struct not_blitz : std::runtime_error {
		using std::runtime_error::runtime_error;
	};

	struct symbol {
		std::string name;
		uint32_t    offset;
	};

	// Names the original compiler gave:
	//   _f<name>    function or command, __MAIN the main program
	//   _v<name>    global variable      _a<name>   global array     _t<name>   type
	//   _<number>   label, _<number>_begin and _<number>_leave around the code of a function
	//   __DATA      the Data statements   __LIBS     the user libraries      __bb*   support functions of the compiler
	enum class symbol_kind { function, global, array, type, label, section, support, other };

	// How the original declares a command of its runtime: "#EntityX%entity%global=0" (return type, name, the type and name of each parameter).
	// The original compiler always passes all parameters, so this is also how many arguments are on the stack.
	struct declaration {
		std::string name;   // As written: EntityX
		char        ret = 'v'; // v nothing, i Int32, f Float32, s String
		std::string params; // One of i, f, s for each parameter
	};

	struct module {
		std::vector<uint8_t>             code;
		std::vector<symbol>              labels;
		std::vector<symbol>              relative; // Names the program uses with a distance (calls and jumps)
		std::vector<symbol>              absolute; // Names the program uses with an address
		std::map<std::string, uint32_t>  defined;  // Name -> offset of labels
		std::map<std::string, declaration> declarations; // The commands of the runtime in the executable, by lowercase name. Empty if loaded as module alone

		static symbol_kind kind(std::string const& name);
	};

	/** Finds the program in an executable (the file, as bytes). Throws not_blitz if there is none. */
	module load_module(std::vector<uint8_t> const& executable);

	/** Reads the declaration of a command ("#EntityX%entity%global=0"), if the text is one. */
	bool parse_declaration(std::string const& text, declaration& out);

	/** The same for the resource alone. */
	module parse_module(uint8_t const* data, size_t size);
} // namespace blitz::recompiler
